    }
    final StatusData data = new StatusData(element, level, msg, t, null);
    msgLock.lock();
    try {
        messages.add(data);
    } finally {
        msgLock.unlock();
    }

    if (listeners.size() > 0) {
          // 如果系统注册了 listener，由 StatusConsoleListener 处理日志
